      "id": "r14907",
      "sub": "problem_debug_3",
      "cat": "problem",
      "role": "fs",
      "roleName": "Full-stack",
      "years": 29.0,
      "text": "Coding for efficiency, understanding interactions between components, debugging multi-threading problems"
